#!/bin/sh
# Тест: опции кодировки SMS применяются НЕЗАВИСИМО от ответа модема на AT.
#
# Дефект, который закрывает тест.
#
# write_conf() вызывался только ПОСЛЕ успешной detect_at_port(). На живом
# устройстве модем не отвечает на AT, пока активен LTE-вызов (в журнале
# устройства: "modem did not answer (AT port is blocked while the LTE data
# call is active)"), поэтому write_conf() не достигался НИКОГДА, а
# /etc/smsd.conf оставался тем, что был записан ещё до патча 0072: с нашим
# маркером "# generated by 40-pejir-sms", но без
#
#   alphabet = utf
#   outgoing_utf8 = yes
#   incoming_utf8 = yes
#
# smsd при этом читал default_alphabet = ISO-8859-15, кириллица
# выбрасывалась с записью в журнал "Cannot convert N character to GSM",
# и русский текст доходил до телефона нечитаемым.
#
# ЛЕЧЕНИЕ: ensure_charset_options() применяет канонические опции кодировки
# к нашему конфигу сразу при старте init-скрипта, не дожидаясь AT-ответа.
# Чужой конфиг (без нашего маркера) не трогаем - update_charset_options()
# теперь проверяет маркер ДО удаления опций, иначе он вырезал бы чужие
# настройки кодировки и оставлял файл без них.
#
# Тест проверяет ПОВЕДЕНИЕ: запускает start_service() в песочнице, где
# AT-порт заведомо не отвечает (detect_at_port() всегда пуст), и смотрит,
# что в итоге оказалось в конфиге.

set -u

if [ -n "${OW_TEST:-}" ]; then
	# OW_TEST задан (в CI это всегда так): отсутствие дерева - ошибка.
	DEFAULT_TREE="$OW_TEST"
	[ -d "$DEFAULT_TREE" ] || { echo "FAIL: нет $DEFAULT_TREE"; exit 1; }
else
	DEFAULT_TREE="/workspace/ow-test"
	[ -d "$DEFAULT_TREE" ] || { echo "FAIL: нет $DEFAULT_TREE (задайте OW_TEST с деревом OpenWrt)"; exit 1; }
fi
TREE="${PEJIR_TREE:-$DEFAULT_TREE}"
INIT="$TREE/package/pejir-sms/root/etc/init.d/40-pejir-sms"

FAILED=0
ok()   { echo "OK: $1"; }
fail() { echo "FAIL: $1"; FAILED=$((FAILED+1)); }

[ -f "$INIT" ] || { echo "FAIL: нет файла $INIT"; exit 1; }

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT INT TERM

MARKER="# generated by 40-pejir-sms"

# Подготовить копию init-скрипта с путями песочницы.
#
# Подменяем: путь конфига, путь пользовательской копии, путь журнала и
# каталоги очереди SMS (/var/spool/sms -> $WORK/spool), чтобы тест ничего
# не писал в реальную систему.
make_init() {
	sed -e "s#^CONF=.*#CONF=\"$WORK/smsd.conf\"#" \
	    -e "s#^USER_CONF=.*#USER_CONF=\"$WORK/smsd.conf.user\"#" \
	    -e "s#^LOG=.*#LOG=\"$WORK/smsd.log\"#" \
	    -e "s#/var/spool/sms#$WORK/spool#g" \
	    "$INIT" > "$WORK/init.sh"
}

# Запустить start_service() в песочнице.
#
# Модем не отвечает: detect_at_port() всегда пуст, ожидание USB-модема
# не блокирует, фоновый повтор не запускается. Именно этот сценарий и был
# на устройстве.
run_start_service() {
	bash -c '
		. "$1"
		usb_modem_present() { return 1; }
		wait_for_modem_usb() { return 1; }
		detect_at_port() { return 1; }
		spawn_retry() { :; }
		logger() { :; }
		start_service
	' _ "$WORK/init.sh" > "$WORK/out.txt" 2>&1
}

# Первая строка секции - граница между глобальной частью и секциями.
section_line() {
	grep -n '^[[:space:]]*\[' "$1" | head -1 | cut -d: -f1
}

opts_in_global_part() {
	local f="$1" sec
	sec="$(section_line "$f")"
	if [ -z "$sec" ]; then
		cat "$f"
	else
		sed -n "1,$((sec - 1))p" "$f"
	fi
}

has_opt() {
	opts_in_global_part "$1" | grep -qxF "$2"
}

make_init

# --- 1) наш конфиг без опций кодировки ------------------------------------
# Именно такое состояние было на устройстве: маркер наш, опций нет.
cat > "$WORK/smsd.conf" <<CONFEOF
#
# Description: Main configuration file for the smsd
#
$MARKER

devices = GM510
incoming = /var/spool/sms/incoming
outgoing = /var/spool/sms/outgoing

[GM510]
device = /dev/ttyUSB2
baudrate = 115200
incoming = yes
outgoing = yes
CONFEOF

run_start_service
RC=$?

if [ "$RC" -eq 0 ]; then
	ok "start_service() отработал без ошибки"
else
	fail "start_service() завершился с кодом $RC: $(tail -3 "$WORK/out.txt" | tr '\n' ' ')"
fi

for opt in "alphabet = utf" "outgoing_utf8 = yes" "incoming_utf8 = yes"; do
	if has_opt "$WORK/smsd.conf" "$opt"; then
		ok "без AT-ответа в глобальной части появилось '$opt'"
	else
		fail "без AT-ответа в глобальной части нет '$opt' - smsd прочитает файл как ISO-8859-15 и потеряет кириллицу"
	fi
done

# Порт не должен потеряться: init-скрипт не имеет права ломать рабочий
# конфиг, только дописывать опции кодировки.
if grep -qxF "device = /dev/ttyUSB2" "$WORK/smsd.conf"; then
	ok "строка device = не потеряна"
else
	fail "строка device = потеряна - init-скрипт испортил рабочий конфиг"
fi

# Опции недопустимы в секции устройства: smsd печатает "Unknown setting
# for modem" и не стартует.
for opt in alphabet outgoing_utf8 incoming_utf8; do
	if opts_in_global_part "$WORK/smsd.conf" | grep -q "^[[:space:]]*$opt[[:space:]]*="; then
		:
	else
		fail "опция $opt потерялась из глобальной части"
	fi
done

SECT="$(section_line "$WORK/smsd.conf")"
if [ -n "$SECT" ]; then
	if sed -n "${SECT},\$p" "$WORK/smsd.conf" | grep -qE '^[[:space:]]*(alphabet|outgoing_utf8|incoming_utf8)[[:space:]]*='; then
		fail "в секции устройства есть глобальные опции кодировки - smsd не запустится"
	else
		ok "в секции устройства глобальных опций нет"
	fi
else
	fail "в конфиге нет ни одной секции - конфиг испорчен"
fi

# --- 2) идемпотентность: второй запуск не дублирует опции ---------------
run_start_service

DUP=""
for opt in "alphabet = utf" "outgoing_utf8 = yes" "incoming_utf8 = yes"; do
	N="$(opts_in_global_part "$WORK/smsd.conf" | grep -cxF "$opt")"
	[ "$N" = "1" ] || DUP="$DUP '$opt'($N)"
done

if [ -z "$DUP" ]; then
	ok "повторный запуск не дублирует опции кодировки"
else
	fail "повторный запуск продублировал опции:$DUP"
fi

# --- 3) чужой конфиг не трогаем -------------------------------------------
# Конфиг без нашего маркера: его настройки кодировки (если они есть)
# принадлежат пользователю, и update_charset_options() не должен их ни
# вырезать, ни переписывать.
cat > "$WORK/smsd.conf" <<CONFEOF
# Конфиг, написанный не нашим скриптом
alphabet = UCS2
outgoing_utf8 = no

[GSM1]
device = /dev/ttyUSB1
CONFEOF
cp "$WORK/smsd.conf" "$WORK/smsd.conf.before"

run_start_service

if cmp -s "$WORK/smsd.conf.before" "$WORK/smsd.conf"; then
	ok "чужой конфиг не изменён"
else
	fail "чужой конфиг изменён: $(diff "$WORK/smsd.conf.before" "$WORK/smsd.conf" | tr '\n' ' ')"
fi

# --- 4) конфига нет вообще ----------------------------------------------
# Нечего обновлять - скрипт не должен падать и не должен создавать
# "полуконфиг" без порта (smsd с таким конфигом не стартует: "There are no
# devices specified.").
rm -f "$WORK/smsd.conf"

run_start_service
RC4=$?

if [ "$RC4" -eq 0 ]; then
	ok "без конфига start_service() не падает"
else
	fail "без конфига start_service() завершился с кодом $RC4"
fi

if [ -f "$WORK/smsd.conf" ]; then
	if grep -q "$MARKER" "$WORK/smsd.conf" && grep -qE '^[[:space:]]*device[[:space:]]*=' "$WORK/smsd.conf"; then
		ok "конфиг без AT-ответа не создан (порта всё равно нет)"
	else
		fail "создан конфиг без порта - smsd не стартует"
	fi
else
	ok "конфиг без AT-ответа не создан"
fi

echo ""
if [ "$FAILED" -eq 0 ]; then
	echo "Все тесты кодировки SMS без AT-ответа пройдены"
	exit 0
fi
echo "Провалено тестов: $FAILED"
exit 1
